const revokeComputerCertificates = `-- name: RevokeComputerCertificates :many
UPDATE agent_certificates
SET revoked_at = now(), revoke_reason = $1::varchar, revoked_by_user_id = $2,
    changed_at = now()
WHERE club_id = $3 AND club_computer_id = $4 AND revoked_at IS NULL
  AND serial <> COALESCE($5::varchar, '')
RETURNING serial
`

type RevokeComputerCertificatesParams struct {
	Reason          string  `json:"reason"`
	RevokedByUserID *int64  `json:"revoked_by_user_id"`
	ClubID          int64   `json:"club_id"`
	ClubComputerID  int64   `json:"club_computer_id"`
	ExceptSerial    *string `json:"except_serial"`
}

// Отзыв всех действующих сертификатов карточки (кроме except_serial, если задан).
func (q *Queries) RevokeComputerCertificates(ctx context.Context, arg RevokeComputerCertificatesParams) ([]string, error) {
	rows, err := q.db.Query(ctx, revokeComputerCertificates,
		arg.Reason,
		arg.RevokedByUserID,
		arg.ClubID,
		arg.ClubComputerID,
		arg.ExceptSerial,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var serial string
		if err := rows.Scan(&serial); err != nil {
			return nil, err
		}
		items = append(items, serial)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

